insert into public.api_audit_events (
  api_id, api_name, company_name, action, actor_name, actor_user_id, details
)
select id, api_name, company_name, 'upload', 'System migration', null,
       'API added by migration 0040 from the provider''s public specification, at the client''s request of 6 October 2026 (thirteen designated APIs).'
  from _0040_api;

-- ------------------------------------------------------------------ postcondition

do $$
declare
  added integer;
  schema_rows integer;
  field_rows integer;
  parameter_rows integer;
begin
  select count(*) into added from public.apis where id in (select id from _0040_api);
  select count(*) into schema_rows from public.api_schema where api_id in (select id from _0040_api);
  select count(*) into field_rows
    from public.api_schema_field f join public.api_schema s on s.id = f.schema_id
   where s.api_id in (select id from _0040_api);
  select count(*) into parameter_rows from public.api_parameter where api_id in (select id from _0040_api);
  if added <> 9 or schema_rows <> 38 or field_rows <> 3579 or parameter_rows <> 18 then
    raise exception '0040 postcondition failed: % APIs, % schemas, % fields, % parameters.', added, schema_rows, field_rows, parameter_rows;
  end if;
end
$$;
